CREATE TABLE IF NOT EXISTS p10_lucky_dailies (player_id BIGINT NOT NULL, day VARCHAR(10) NOT NULL, fireworks_used INT NOT NULL, drop_batches INT NOT NULL, snatched INT NOT NULL, fireworks_at BIGINT NOT NULL, drop_at BIGINT NOT NULL, drop_request_hash VARCHAR(64) NOT NULL, drop_response LONGBLOB NULL, PRIMARY KEY(player_id,day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
